55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const policyBasePremium = (items: Item[]): number => {
74	  if (items.length === BLOCK_SIZE) {
75	    return BLOCK_BASE_PREMIUM;
76	  }
77	  return items.reduce((sum, item) => sum + itemBasePremium(item), 0);
78	};
79	
80	const withFirstInsuranceSurcharge = (policyBase: number): number =>
81	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
82	
83	const roundInMHPCOsFavor = Math.ceil;
84	
85	const quotePremium = (items: Item[]): number =>
86	  roundInMHPCOsFavor(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
87	
88	const runStep = (step: Step): StepResult => {
89	  if (step.op === "quote") {
90	    return { premium: quotePremium(step.items) };
91	  }
92	  throw new Error(`Unsupported step: ${step.op}`);
93	};
94	
95	export const runScenario = (scenario: Scenario): ScenarioResult => ({
96	  results: scenario.steps.map(runStep),
97	});
