const formsBuildingBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const policyBasePremium = (items: Item[]): number =>
  formsBuildingBlock(items) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(items);
